import time
from typing import List, Sequence


def one_turn_comb(A: Sequence[int], m: int, time_limit: float = 10.0) -> List[int]:
    """Given a snake A in Q_m (transitions from vertex 0), find a snake B in Q_m that
    starts at A's endpoint and avoids A's other vertices.  Then A + [m] + B is a snake
    in Q_{m+1} whose row sequence in Q_1 x Q_m is a comb with exactly one turn."""
    verts = [0]
    for c in A:
        verts.append(verts[-1] ^ (1 << c))
    forbidden, u = set(verts[:-1]), verts[-1]
    best: List[int] = []
    deadline = time.time() + time_limit

    def ok(w: int, on: set, v: int) -> bool:
        if w in forbidden or w in on:
            return False
        return not any((w ^ (1 << j)) in on and (w ^ (1 << j)) != v for j in range(m))

    def rec(path: List[int], on: set, tr: List[int]) -> None:
        nonlocal best
        if len(tr) > len(best):
            best = list(tr)
        if time.time() > deadline:
            return
        v = path[-1]
        for i in range(m):
            w = v ^ (1 << i)
            if ok(w, on, v):
                path.append(w); on.add(w); tr.append(i)
                rec(path, on, tr)
                path.pop(); on.discard(w); tr.pop()

    rec([u], {u}, [])
    return best


if __name__ == "__main__":
    A = [1, 2, 3, 1, 0, 4, 3, 0, 5, 4, 0, 1, 3, 4, 0, 2, 4, 1, 0, 4, 3, 1, 5, 3, 4]
    B = one_turn_comb(A, 6, 8)
    print("Q_7 snake of length", len(A) + 1 + len(B), "=", len(A), "+ 1 +", len(B))
